# Solve the SF day scheduling problem via backtracking search.

from itertools import permutations

def to_minutes(h, m, ampm):
    if ampm.upper() == 'AM':
        h24 = h % 12
    else:
        h24 = (h % 12) + 12
    return h24 * 60 + m

def fmt_time(t):
    t = t % (24*60)
    h24 = t // 60
    m = t % 60
    ampm = 'AM' if h24 < 12 else 'PM'
    h12 = h24 % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{ampm}"

# Travel times (directed, minutes)
dist = {
    'Embarcadero': {
        'Union Square': 10, 'Golden Gate Park': 25, 'Chinatown': 7, 'The Castro': 25
    },
    'Union Square': {
        'Embarcadero': 11, 'Golden Gate Park': 22, 'Chinatown': 7, 'The Castro': 19
    },
    'Golden Gate Park': {
        'Embarcadero': 25, 'Union Square': 22, 'Chinatown': 23, 'The Castro': 13
    },
    'Chinatown': {
        'Embarcadero': 5, 'Union Square': 7, 'Golden Gate Park': 23, 'The Castro': 22
    },
    'The Castro': {
        'Embarcadero': 22, 'Union Square': 19, 'Golden Gate Park': 11, 'Chinatown': 20
    }
}

# Friends data
friends = {
    'Deborah': {
        'loc': 'Union Square',
        'start': to_minutes(6, 0, 'PM'),
        'end': to_minutes(7, 45, 'PM'),
        'min': 90
    },
    'Joseph': {
        'loc': 'Golden Gate Park',
        'start': to_minutes(5, 30, 'PM'),
        'end': to_minutes(9, 15, 'PM'),
        'min': 120
    },
    'Jeffrey': {
        'loc': 'Chinatown',
        'start': to_minutes(7, 0, 'AM'),
        'end': to_minutes(7, 45, 'AM'),
        'min': 30
    },
    'Lisa': {
        'loc': 'The Castro',
        'start': to_minutes(1, 45, 'PM'),
        'end': to_minutes(4, 0, 'PM'),
        'min': 30
    }
}

start_loc = 'Embarcadero'
start_time = to_minutes(9, 0, 'AM')

def compare_plans(p1, p2):
    # Compare by: number met, total meet minutes, less travel, less wait
    key1 = (len(p1['meetings']), p1['meet_minutes'], -p1['travel_minutes'], -p1['wait_minutes'])
    key2 = (len(p2['meetings']), p2['meet_minutes'], -p2['travel_minutes'], -p2['wait_minutes'])
    return (key1 > key2) - (key1 < key2)

def best_plan_from(curr_loc, curr_time, visited):
    best = {'meetings': [], 'meet_minutes': 0, 'travel_minutes': 0, 'wait_minutes': 0}
    # Try adding each remaining friend
    for name, f in friends.items():
        if name in visited:
            continue
        # Travel to friend
        travel = dist[curr_loc][f['loc']]
        arrival = curr_time + travel
        start = max(arrival, f['start'])
        # Must fit at least minimum duration within availability window
        if start + f['min'] > f['end']:
            continue
        # Candidate durations: minimum and maximum
        max_possible = f['end'] - start
        durations = [f['min']]
        if max_possible != f['min']:
            durations.append(max_possible)
        for d in durations:
            end = start + d
            wait = max(0, start - arrival)
            suffix = best_plan_from(f['loc'], end, visited | {name})
            # Combine metrics
            meetings = [{'name': name, 'loc': f['loc'], 'start': start, 'end': end, 'duration': d}] + suffix['meetings']
            meet_minutes = d + suffix['meet_minutes']
            travel_minutes = travel + suffix['travel_minutes']
            wait_minutes = wait + suffix['wait_minutes']
            cand = {
                'meetings': meetings,
                'meet_minutes': meet_minutes,
                'travel_minutes': travel_minutes,
                'wait_minutes': wait_minutes
            }
            if compare_plans(cand, best) > 0:
                best = cand
    return best

best = best_plan_from(start_loc, start_time, set())

# Build narrative
lines = []
lines.append(f"You start at {start_loc} at {fmt_time(start_time)}.")

curr_loc = start_loc
curr_time = start_time

for m in best['meetings']:
    travel = dist[curr_loc][m['loc']]
    arrival = curr_time + travel
    lines.append(f"You travel to {m['loc']} in {travel} minutes and arrive at {fmt_time(arrival)}.")
    if arrival < m['start']:
        lines.append(f"You wait until {fmt_time(m['start'])}.")
    lines.append(f"You meet {m['name']} for {m['duration']} minutes from {fmt_time(m['start'])} to {fmt_time(m['end'])}.")
    curr_loc = m['loc']
    curr_time = m['end']

# Print resulting schedule list (as in the example format)
print(lines)

