from itertools import permutations, combinations

def fmt_time(m):
    h = (m // 60) % 24
    mi = m % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{mi:02d}{suffix}"

# Directed travel times (minutes)
travel = {
    "Bayview": {
        "Union Square": 17, "Embarcadero": 19, "Russian Hill": 23, "Pacific Heights": 23
    },
    "Union Square": {
        "Bayview": 15, "Embarcadero": 11, "Russian Hill": 13, "Pacific Heights": 15
    },
    "Embarcadero": {
        "Bayview": 21, "Union Square": 10, "Russian Hill": 8, "Pacific Heights": 11
    },
    "Russian Hill": {
        "Bayview": 23, "Union Square": 11, "Embarcadero": 8, "Pacific Heights": 7
    },
    "Pacific Heights": {
        "Bayview": 22, "Union Square": 12, "Embarcadero": 10, "Russian Hill": 7
    }
}

# Friends: location, window [start, end], min meeting minutes
friends = {
    "Andrew":  {"location": "Union Square",    "start": 17*60,    "end": 20*60+15, "min": 120},
    "Kevin":   {"location": "Embarcadero",     "start": 17*60+30, "end": 20*60+45, "min": 45},
    "Barbara": {"location": "Russian Hill",    "start": 10*60,    "end": 16*60+15, "min": 60},
    "Deborah": {"location": "Pacific Heights", "start": 13*60,    "end": 20*60+30, "min": 120},
}

start_loc = "Bayview"
start_time = 9*60  # 9:00 AM

def simulate(order):
    steps = [f"You start at {start_loc} at {fmt_time(start_time)}."]
    cur_loc = start_loc
    cur_time = start_time
    total_wait = 0

    for name in order:
        info = friends[name]
        dest = info["location"]
        t_travel = travel[cur_loc][dest] if cur_loc != dest else 0
        if t_travel > 0:
            cur_time += t_travel
            steps.append(f"You travel to {dest} in {t_travel} minutes and arrive at {fmt_time(cur_time)}.")
        # arrival
        arrival = cur_time
        w_start, w_end, min_dur = info["start"], info["end"], info["min"]
        start_meet = max(arrival, w_start)
        # feasibility check
        if start_meet + min_dur > w_end:
            return None  # infeasible in this order
        # wait if needed
        if arrival < w_start:
            steps.append(f"You wait until {fmt_time(start_meet)}.")
            total_wait += (start_meet - arrival)
        end_meet = start_meet + min_dur
        steps.append(f"You meet {name} for {min_dur} minutes from {fmt_time(start_meet)} to {fmt_time(end_meet)}.")
        cur_time = end_meet
        cur_loc = dest

    # Optional: end-of-day note
    steps.append(f"You end your day at {cur_loc} at {fmt_time(cur_time)}.")
    return {
        "steps": steps,
        "count": len(order),
        "wait": total_wait,
        "finish": cur_time
    }

best = None

people = list(friends.keys())
# Try all subsets (largest to smallest) and permutations
for r in range(len(people), -1, -1):
    for subset in combinations(people, r):
        for order in permutations(subset):
            result = simulate(order)
            if result is None:
                continue
            if best is None:
                best = result
            else:
                # Prefer more friends, then less waiting, then earlier finish
                if (result["count"] > best["count"] or
                    (result["count"] == best["count"] and result["wait"] < best["wait"]) or
                    (result["count"] == best["count"] and result["wait"] == best["wait"] and result["finish"] < best["finish"])):
                    best = result
    if best and best["count"] == len(people):
        # Can't do better than meeting everyone
        break

# Output in the requested format: a Python list of strings
plan = best["steps"] if best else [f"You start at {start_loc} at {fmt_time(start_time)}.", "No feasible meetings found."]
print(plan)

