            if loc not in dist or to_loc not in dist[loc]:
                return None
            travel = dist[loc][to_loc]
        arrival = time + travel
        steps.append(f"You travel to {to_loc} in {travel} minutes and arrive at {fmt_time(arrival)}.")
        total_travel += travel

        # Wait if early
        window_start = info["start"]
        window_end = info["end"]
        dur = info["dur"]
        if arrival < window_start:
            steps.append(f"You wait until {fmt_time(window_start)}.")
            total_wait += (window_start - arrival)
            arrival = window_start

        # Can we fit the meeting?
        start_meet = max(arrival, window_start)
        end_meet = start_meet + dur
        if end_meet > window_end:
            return None

        steps.append(f"You meet {name} for {dur} minutes from {fmt_time(start_meet)} to {fmt_time(end_meet)}.")
        time = end_meet
        loc = to_loc

    return {
        "steps": steps,
        "count": len(order),
        "end_time": time,
        "idle_travel": total_wait + total_travel
    }

