name_to_idx = {f[0]: i for i, f in enumerate(friends)}

START_LOC = "Golden Gate Park"
START_TIME = to_minutes(9, 0, 'AM')

# DFS with memoization; objective: maximize (count, -finish_time, -wait_time)
@lru_cache(None)
def best(current_loc, current_time, met_mask):
    best_score = (0, -current_time, 0)  # count=0, finish_time=current_time, wait=0
    best_plan = []
    n = len(friends)

    # Try visiting each not-yet-met friend if feasible
    for i in range(n):
        if (met_mask >> i) & 1:
            continue
        name, loc, wstart, wend, dur = friends[i]
        # If we can't travel (no edge), skip
        if current_loc not in travel or loc not in travel[current_loc]:
            continue

        arr = current_time + travel[current_loc][loc]
        meet_start = max(arr, wstart)
        meet_end = meet_start + dur
        if meet_end > wend:
            continue  # infeasible

        wait = max(0, meet_start - arr)

        # Recurse
        sub_score, sub_plan = best(loc, meet_end, met_mask | (1 << i))

        # Build current step events
        step = []
        step.append(f"You travel to {loc} in {travel[current_loc][loc]} minutes and arrive at {fmt_time(arr)}.")
        if wait > 0:
            step.append(f"You wait until {fmt_time(meet_start)}.")
        step.append(f"You meet {name} for {dur} minutes from {fmt_time(meet_start)} to {fmt_time(meet_end)}.")

        # Combine scores
        # sub_score is (count, -finish_time, -wait_time) from the recursion
        count = sub_score[0] + 1
        finish_time = -sub_score[1]  # recover finish time
        if count == 1:
            finish_time = meet_end  # if this is the first met in this branch
        else:
            # finish_time already equals the recursive finish time; OK
            pass
        total_wait = -sub_score[2] + wait

        curr_score = (count, -finish_time, -total_wait)

        if curr_score > best_score:
            best_score = curr_score
            best_plan = step + sub_plan

    return best_score, best_plan

# Run the search
score, plan_rest = best(START_LOC, START_TIME, 0)
plan = [f"You start at {START_LOC} at {fmt_time(START_TIME)}."] + plan_rest

